const jobItems    = $('Extract Company IDs').first().json.job_items || [];
const companyRows = $('Read companies').all().map(i => i.json);
const run_id      = $('Extract Company IDs').first().json.run_id;

const companyMap = {};
for (const c of companyRows) {
  companyMap[String(c.company_uid)] = c;
}

const grouped = {};
for (const job of jobItems) {
  const cid     = String(job['company ID'] || job.company_id || '').trim();
  const company = companyMap[cid];
  if (!company) continue;

  if (!grouped[cid]) {
    const website = (company.company_website || '').trim();
    grouped[cid] = {
      company_uid:         company.company_uid,
      company_name:        company.company_name     || '',
      company_website:     website.endsWith('/') ? website.slice(0, -1) : website,
      company_industry:    company.company_industry || '',
      company_size:        company.company_size     || '',
      company_linkedin_id: company.company_linkedin_id || '',
      run_id:              run_id,
      job_titles: []
    };
  }

  const jt = (job['Job title'] || job.job_title || '').trim();
  if (jt && !grouped[cid].job_titles.includes(jt)) {
    grouped[cid].job_titles.push(jt);
  }
}

return Object.values(grouped)
  .filter(c => c.company_website && c.company_website.length > 5)
  .map(c => ({ json: c }));

// ==========================================================
// PREPARE APIFY PAYLOAD
// Sends BOTH company_website AND company_alternate_domain to
// Apify so leads are found regardless of which domain the
// company operates under (e.g. jts.com + johnsonthermal.com).
// ==========================================================

const FUNCTIONAL_MAP = [
  { kw: ['finance','financial','accounting','accountant','controller','tax','cfo','treasurer'], fn: 'finance' },
  { kw: ['hr','human resources','recruiter','talent','people ops','hris','workforce','staffing'], fn: 'human_resources' },
  { kw: ['operations','operations manager','operations director','vp operations','supply chain','logistics','warehouse','distribution'], fn: 'operations' },
  { kw: ['engineer','engineering','software','mechanical','electrical','manufacturing','plant manager','production'], fn: 'engineering' },
  { kw: ['sales','account executive','business development','revenue','growth'], fn: 'sales' },
  { kw: ['marketing','brand','communications','pr','content','seo'], fn: 'marketing' },
  { kw: ['legal','attorney','counsel','compliance','paralegal'], fn: 'legal' },
  { kw: ['construction','site manager','project manager','civil'], fn: 'operations' },
];

function getFunctionalLevels(jobTitles) {
  const levels = new Set(['human_resources', 'operations']);
  for (const jt of jobTitles) {
    const t = (jt || '').toLowerCase();
    for (const { kw, fn } of FUNCTIONAL_MAP) {
      if (kw.some(k => t.includes(k))) levels.add(fn);
    }
  }
  return [...levels];
}

const companies = items.map(i => i.json);

// Collect all domains — primary + alternate — deduped and non-empty
const allDomains = [];
const seenDomains = new Set();
for (const c of companies) {
  for (const raw of [c.company_website, c.company_alternate_domain]) {
    const d = (raw || '').trim().replace(/\/+$/, '');
    if (d && !seenDomains.has(d)) {
      seenDomains.add(d);
      allDomains.push(d);
    }
  }
}

const allJobTitles    = companies.flatMap(c => c.job_titles || []);
const functionalLevels = getFunctionalLevels(allJobTitles);

const apify_body = {
  company_domain:  allDomains,
  email_status:    ['validated'],
  fetch_count:     50,
  functional_level: functionalLevels,
  seniority_level: ['owner', 'c_suite', 'director', 'vp', 'head', 'manager']
};

return [{
  json: {
    apify_body,
    batch_companies: companies   // carries company_alternate_domain for Process & Tag
  }
}];

// ==========================================================
// PROCESS & TAG ALL LEADS
//
// MATCH PRIORITY (in order):
//   1. LinkedIn UID  — company_linkedin_uid from Apify vs
//                      company_linkedin_id in batch (fast, exact)
//   2. Email domain  — extract domain from lead's work email,
//                      check against BOTH company_website AND
//                      company_alternate_domain in batch
//
// ROUTES:
//   raw_lead      → matched lead with valid company_uid
//   unidentified  → Apify returned a person but zero company
//                   fields — person data is valid and stored
//                   in unidentified_poc_leads for dashboard use
//   no_poc        → company got zero leads back via any path
//
// NO-POC DETECTION:
//   Uses matchedCompanyUids — a company is no_poc only if
//   ZERO leads matched it (raw_lead OR unidentified both count)
// ==========================================================

const PERSONAL_DOMAINS = new Set([
  'gmail.com','yahoo.com','hotmail.com','outlook.com',
  'icloud.com','aol.com','me.com','live.com','protonmail.com',
  'ymail.com','msn.com','mail.com'
]);

function safeUID(val) {
  const s = String(val ?? '').trim();
  return (s && s !== '0') ? s : '';
}

function extractDomain(url) {
  if (!url) return '';
  return (url + '')
    .toLowerCase().trim()
    .replace(/https?:\/\//i, '')
    .split('/')[0]
    .replace(/^www\./, '')
    .trim();
}

function getEmailDomain(email) {
  if (!email || !email.includes('@')) return '';
  const d = email.split('@')[1].toLowerCase().trim();
  return PERSONAL_DOMAINS.has(d) ? '' : d;
}

// ── Load batch context ────────────────────────────────────────────────────
const batchCompanies = $('Prepare Apify Payload').first().json.batch_companies || [];
const leads          = items.map(i => i.json);
const run_id         = batchCompanies[0]?.run_id || null;

// ── Build LinkedIn UID lookup ─────────────────────────────────────────────
const linkedinMap = {};
for (const c of batchCompanies) {
  const uid = safeUID(c.company_linkedin_id);
  if (uid) linkedinMap[uid] = c;
}

// ── Build domain lookup (primary + alternate) ─────────────────────────────
const domainMap = {};
for (const c of batchCompanies) {
  const primary   = extractDomain(c.company_website);
  const alternate = extractDomain(c.company_alternate_domain);
  if (primary)   domainMap[primary]   = c;
  if (alternate) domainMap[alternate] = c;
}

// ── Build searched_domain map: domain → company (for unidentified context)
// Maps the exact domain that was sent to Apify back to the company object
const searchedDomainMap = {};
for (const c of batchCompanies) {
  const primary   = extractDomain(c.company_website);
  const alternate = extractDomain(c.company_alternate_domain);
  if (primary)   searchedDomainMap[primary]   = c;
  if (alternate) searchedDomainMap[alternate] = c;
}

// Track which companies got at least one lead (matched OR unidentified)
const matchedCompanyUids = new Set();

const output = [];

// ── SECTION B: Process each Apify lead ───────────────────────────────────
for (const lead of leads) {
  let matched = null;

  // Path 1 — LinkedIn UID
  const leadLinkedInUID = safeUID(lead.company_linkedin_uid ?? lead.company_linkedin_id);
  if (leadLinkedInUID) {
    matched = linkedinMap[leadLinkedInUID] || null;
  }

  // Path 2 — Email domain fallback
  if (!matched) {
    const workEmailDomain = getEmailDomain(lead.email || '');
    if (workEmailDomain) {
      matched = domainMap[workEmailDomain] || null;
    }
  }

  // ── Path 3 — Unidentified: valid person, no company link ─────────────
  // Apify returned this person but with all company fields empty.
  // We cannot link them to a company_uid (FK constraint) but their
  // person data is real and valuable. Store in unidentified_poc_leads.
  if (!matched || !matched.company_uid || String(matched.company_uid) === '0') {

    // Still mark company as "got results" if email hints at a searched domain
    const emailDomain     = getEmailDomain(lead.email || '');
    const hintedCompany   = emailDomain ? searchedDomainMap[emailDomain] : null;
    if (hintedCompany) matchedCompanyUids.add(String(hintedCompany.company_uid));

    // Only store if person has at least a name or email — skip truly empty rows
    const hasPersonData = (lead.first_name || lead.last_name || lead.email || lead.linkedin);
    if (!hasPersonData) continue;

    output.push({
      json: {
        _route: 'unidentified',
        // Person — always captured
        first_name:       lead.first_name       || '',
        last_name:        lead.last_name        || '',
        full_name:        lead.full_name        || `${lead.first_name || ''} ${lead.last_name || ''}`.trim(),
        job_title:        lead.job_title        || lead.position || '',
        headline:         lead.headline         || '',
        seniority_level:  lead.seniority_level  || lead.seniority || '',
        email:            lead.email            || '',
        personal_email:   lead.personal_email   || '',
        mobile_number:    lead.mobile_number    || lead.phone || '',
        linkedin:         lead.linkedin         || lead.linkedinUrl || lead.linkedin_url || '',
        city:             lead.city             || '',
        state:            lead.state            || '',
        country:          lead.country          || '',
        // Company hints — best effort, may be empty
        inferred_domain:  emailDomain           || '',
        searched_domain:  hintedCompany ? extractDomain(hintedCompany.company_website) : '',
        company_size:     lead.company_size     || (hintedCompany ? hintedCompany.company_size : '') || '',
        industry:         lead.industry         || (hintedCompany ? hintedCompany.company_industry : '') || '',
        run_id:          run_id
      }
    });
    continue;
  }

  // ── Matched lead — tag as raw_lead ────────────────────────────────────
  matchedCompanyUids.add(String(matched.company_uid));
  const leadDomain = extractDomain(lead.company_website || lead.domain || '');

  output.push({
    json: {
      _route: 'raw_lead',
      first_name:           lead.first_name           || '',
      last_name:            lead.last_name            || '',
      full_name:            lead.full_name            || `${lead.first_name || ''} ${lead.last_name || ''}`.trim(),
      job_title:            lead.job_title            || lead.position || '',
      headline:             lead.headline             || '',
      seniority_level:      lead.seniority_level      || lead.seniority || '',
      email:                lead.email                || '',
      personal_email:       lead.personal_email       || '',
      mobile_number:        lead.mobile_number        || lead.phone || '',
      linkedin:             lead.linkedin             || lead.linkedinUrl || lead.linkedin_url || '',
      city:                 lead.city                 || '',
      state:                lead.state                || '',
      country:              lead.country              || '',
      company_uid:          matched.company_uid,
      company_name:         lead.company_name         || matched.company_name      || '',
      company_domain:       leadDomain,
      company_website:      lead.company_website      || lead.domain               || '',
      company_linkedin:     lead.company_linkedin     || lead.company_linkedin_url || '',
      company_linkedin_uid: leadLinkedInUID           || '',
      company_size:         lead.company_size         || matched.company_size      || '',
      industry:             lead.industry             || matched.company_industry  || '',
      original_job_titles:  (matched.job_titles       || []).join(' | '),
      run_id:              run_id
    }
  });
}

// ── SECTION A: Tag no-POC companies ──────────────────────────────────────
for (const company of batchCompanies) {
  if (!matchedCompanyUids.has(String(company.company_uid))) {
    output.push({
      json: {
        _route:              'no_poc',
        company_uid:         company.company_uid,
        company_name:        company.company_name,
        company_website:     company.company_website,
        company_industry:    company.company_industry,
        job_titles_searched: (company.job_titles || []).join(' | ')
      }
    });
  }
}

return output;

// Keep only the columns that exist in no_poc_companies table
return items
  .filter(i => i.json._route === 'no_poc')
  .map(i => ({
    json: {
      company_uid:         i.json.company_uid,
      company_name:        i.json.company_name,
      company_website:     i.json.company_website,
      company_industry:    i.json.company_industry,
      job_titles_searched: i.json.job_titles_searched
    }
  }));

// Strip routing/internal fields — keep only poc_leads table columns.
// Guard 1: drop any item where company_uid is null, 0, or falsy.
// Guard 2: deduplicate by (company_uid, linkedin) — Apollo returns the
//          same person twice when a company has multiple domains sent
//          to Apify (primary + alternate). This prevents duplicate key errors.

const seen = new Set();

return items
  .filter(i => {
    const uid = i.json.company_uid;
    return uid && String(uid) !== '0';
  })
  .filter(i => {
    const linkedin = (i.json.linkedin || '').trim();
    if (!linkedin) return true; // no linkedin — allow, FK won't deduplicate these
    const key = `${i.json.company_uid}__${linkedin}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .map(i => ({
    json: {
      company_uid:           i.json.company_uid,
      first_name:            i.json.first_name            || '',
      last_name:             i.json.last_name             || '',
      full_name:             i.json.full_name             || '',
      job_title:             i.json.job_title             || '',
      headline:              i.json.headline              || '',
      seniority_level:       i.json.seniority_level       || '',
      email:                 i.json.email                 || '',
      personal_email:        i.json.personal_email        || '',
      mobile_number:         i.json.mobile_number         || '',
      linkedin:              i.json.linkedin              || '',
      city:                  i.json.city                  || '',
      state:                 i.json.state                 || '',
      country:               i.json.country               || '',
      company_name:          i.json.company_name          || '',
      company_domain:        i.json.company_domain        || '',
      company_website:       i.json.company_website       || '',
      company_linkedin:      i.json.company_linkedin      || '',
      company_linkedin_uid:  i.json.company_linkedin_uid  || '',
      company_size:          i.json.company_size          || '',
      industry:              i.json.industry              || '',
      original_job_titles:   i.json.original_job_titles   || '',
      run_id:                i.json.run_id                || null
    }
  }));

// PASSTHROUGH — do not write to DB here.
// poc_leads — written by Create a row1 (Supabase)
// Pass items through so the loop-back connection fires correctly.
return $input.all();

/* =================================================================
   PHASE 2B — Score Leads (POC Preference Logic)

   NOTE: _route check intentionally removed.
   The Switch node upstream already guarantees only raw_lead
   items reach this node. Adding the check causes silent failures
   when n8n fan-out doesn't preserve custom fields perfectly.
   ================================================================= */

const JOB_CATEGORY_POC_MAP = [
  { kw: ['controller'], poc: ['finance director','chief financial officer','cfo','head of finance'] },
  { kw: ['finance manager','finance director','financial analyst','financial controller','financial'], poc: ['finance director','chief financial officer','cfo','head of finance'] },
  { kw: ['accounting','accountant','accounts payable','accounts receivable'], poc: ['accounting director','chief financial officer','cfo'] },
  { kw: ['construction manager','construction director','site manager'], poc: ['construction director','construction manager'] },
  { kw: ['manufacturing','plant manager','production manager'], poc: ['manufacturing director','operations manager','operations director'] },
  { kw: ['human resources','hr manager','hr director','talent acquisition','recruiter','hris','talent management'], poc: ['head of hr','hr director','recruitment manager','talent acquisition lead'] },
  { kw: ['operations manager','operations director','vp operations','operations head'], poc: ['operations manager','operations director','vp operations'] },
  { kw: ['supply chain','logistics','warehouse','distribution','production planning','inventory'], poc: ['manufacturing director','operations manager','operations director','vp operations'] },
  { kw: ['sales manager','account executive','business development','sales director','head of sales','sales'], poc: ['business development manager','sales director','head of sales'] },
  { kw: ['banking','loan officer','mortgage','branch manager'], poc: ['branch manager'] },
  { kw: ['tax analyst','tax manager','tax director','tax accountant','tax specialist'], poc: ['head of tax','tax director','chief financial officer','cfo'] },
  { kw: ['engineering manager','head of engineering','engineering director','software engineer','mechanical engineer','engineer'], poc: ['head of engineering','director of engineering','vp engineering'] },
  { kw: ['legal','attorney','counsel','law','litigation','paralegal','compliance'], poc: ['chief administrative officer','managing partner','chief human resources officer','chro','hr director','head of hr'] },
  { kw: ['real estate','property','maintenance','facilities'], poc: ['director of operations','chief operating officer','coo','hr director'] },
  { kw: ['executive assistant','office manager','administrative'], poc: ['chief operating officer','coo','chief administrative officer','hr director'] },
];

const DEFAULT_POC = [
  'hr director','head of hr','chro','chief human resources officer',
  'recruitment manager','talent acquisition lead',
  'chief operating officer','coo','operations manager','vp operations'
];

function lc(v) { return (v || '').toLowerCase(); }

function isPersonalEmail(email) {
  return /@(gmail|yahoo|outlook|hotmail|icloud|aol|protonmail|me\.com|live\.|ymail)/i.test(email || '');
}

// Hard-reject only truly junior/non-decision-maker roles
// NOTE: "administrator" removed — "Chief Administrative Officer" was being falsely rejected
function isHardReject(title) {
  const t = lc(title);
  const rejectTerms = [
    'intern','internship','student','entry level','entry-level',
    'junior ', ' jr.', ' jr ',
    'receptionist','secretary','clerk',
    'temp ','temporary','part-time','part time'
  ];
  return rejectTerms.some(k => t.includes(k));
}

function mapJobTitleToPOC(jobTitle) {
  const t = lc(jobTitle);
  for (const entry of JOB_CATEGORY_POC_MAP) {
    if (entry.kw.some(k => t.includes(k))) return entry.poc;
  }
  return DEFAULT_POC;
}

function scoreEmail(lead) {
  const work     = lead.email          || '';
  const personal = lead.personal_email || '';
  const li       = lead.linkedin       || '';
  if (work && !isPersonalEmail(work))  return { score: 30, selected_email: work,     email_type: 'work_verified' };
  if (work &&  isPersonalEmail(work))  return { score: 20, selected_email: work,     email_type: 'personal_domain' };
  if (personal)                        return { score: 20, selected_email: personal,  email_type: 'personal' };
  if (li)                              return { score: 5,  selected_email: null,       email_type: 'linkedin_only' };
  return                                      { score: -999, selected_email: null,     email_type: 'none' };
}

function scorePOCMatch(leadTitle, preferredTitles) {
  const lt = lc(leadTitle);
  for (let i = 0; i < preferredTitles.length; i++) {
    if (lt.includes(preferredTitles[i])) return Math.max(50 - (i * 3), 10);
  }
  return 0;
}

function scoreHRFallback(leadTitle) {
  const t = lc(leadTitle);
  return [
    'hr ',' hr','human resources','talent acquisition','talent management',
    'people operations','people & culture','people ops','workforce',
    'recruiter','recruiting','recruitment','staffing','hris','onboarding',
    'chro','chief human'
  ].some(k => t.includes(k)) ? 20 : 0;
}

function scoreSeniority(leadTitle) {
  const t = lc(leadTitle);
  const tiers = [
    { terms: ['ceo','coo','cto','cfo','chro','chief ','founder','owner','president','managing partner','c-suite'], pts: 15 },
    { terms: ['vice president','vp '], pts: 13 },
    { terms: ['director','head of','partner'], pts: 11 },
    { terms: ['manager','lead '], pts: 8 },
    { terms: ['senior ','sr.','sr '], pts: 5 }
  ];
  for (const tier of tiers) {
    if (tier.terms.some(term => t.includes(term))) return tier.pts;
  }
  return 0;
}

// ── Main scoring loop ─────────────────────────────────────────────
const scoredLeads = [];

for (const lead of items.map(i => i.json)) {

  // Skip no_poc router tags if they somehow arrive (defensive only)
  if (lead._route === 'no_poc') continue;

  const title = lead.job_title || '';

  // Hard reject check
  if (isHardReject(title)) continue;

  // Email gate — must have at least linkedin to be contactable
  const emailResult = scoreEmail(lead);
  if (emailResult.score < 0) continue;

  // Derive preferred POC from original job titles on the company posting
  const originalJobTitles = (lead.original_job_titles || '')
    .split(' | ').map(t => t.trim()).filter(Boolean);

  const preferredPOC = originalJobTitles.length > 0
    ? [...new Set(originalJobTitles.flatMap(jt => mapJobTitleToPOC(jt)))]
    : DEFAULT_POC;

  // Score all dimensions
  const pocMatch      = scorePOCMatch(title, preferredPOC);
  const hrFallback    = pocMatch === 0 ? scoreHRFallback(title) : 0;
  const seniority     = (pocMatch === 0 && hrFallback === 0) ? scoreSeniority(title) : 0;
  const linkedinBonus = lead.linkedin ? 5 : 0;
  const total         = emailResult.score + pocMatch + hrFallback + seniority + linkedinBonus;

  scoredLeads.push({
    json: {
      // Score metadata
      partner_confidence_score: total,
      _score_breakdown: {
        email:          emailResult.score,
        poc_match:      pocMatch,
        hr_fallback:    hrFallback,
        seniority,
        linkedin_bonus: linkedinBonus,
        total
      },
      _context: {
        original_job_titles:      originalJobTitles,
        preferred_poc_titles:     preferredPOC,
        poc_match_fired:          pocMatch > 0,
        hr_fallback_fired:        hrFallback > 0,
        seniority_fallback_fired: seniority > 0
      },
      poc_id:           lead.poc_id,
      // Person
      first_name:      lead.first_name      || '',
      last_name:       lead.last_name       || '',
      full_name:       lead.full_name       || '',
      job_title:       title,
      headline:        lead.headline        || '',
      seniority_level: lead.seniority_level || '',
      selected_email:  emailResult.selected_email,
      email_type:      emailResult.email_type,
      email:           lead.email           || '',
      personal_email:  lead.personal_email  || '',
      mobile_number:   lead.mobile_number   || '',
      linkedin:        lead.linkedin        || '',
      city:            lead.city            || '',
      state:           lead.state           || '',
      country:         lead.country         || '',
      // Company
      company_uid:          lead.company_uid,
      company_name:         lead.company_name         || '',
      company_domain:       lead.company_domain       || '',
      company_website:      lead.company_website      || '',
      company_linkedin:     lead.company_linkedin     || '',
      company_linkedin_uid: lead.company_linkedin_uid || '',
      company_size:         lead.company_size         || '',
      industry:             lead.industry             || '',
      poc_id: lead.poc_id || null, 
      run_id:               lead.run_id               || null
    }
  });
}

return scoredLeads;

/* =================================================================
   PHASE 2B — Group by Company → Select Top 2 POCs
   Tie-breaking order: POC match → email quality → HR fallback → seniority
   Output includes flattened scores ready for DB insert.
   ================================================================= */

function num(v) { return Number.isFinite(Number(v)) ? Number(v) : 0; }

function compareLeads(a, b) {
  const sb = b._score_breakdown || {}, sa = a._score_breakdown || {};
  const totalDiff = num(b.partner_confidence_score) - num(a.partner_confidence_score);
  if (totalDiff !== 0) return totalDiff;
  for (const field of ['poc_match','email','hr_fallback','seniority']) {
    const diff = num(sb[field]) - num(sa[field]);
    if (diff !== 0) return diff;
  }
  return 0;
}

const allLeads = items.map(i => i.json);

const byCompany = {};
for (const lead of allLeads) {
  const key = String(lead.company_uid || 'unknown');
  if (!byCompany[key]) byCompany[key] = [];
  byCompany[key].push(lead);
}

const selected = [];

for (const [key, leads] of Object.entries(byCompany)) {
  if (!leads.length) continue;

  const isDirect = leads.length <= 2;
  const top2 = [...leads].sort(compareLeads).slice(0, 2);

  for (let i = 0; i < top2.length; i++) {
    const lead = top2[i];
    const sb   = lead._score_breakdown || {};

    const reasons = [];
    if (isDirect) {
      reasons.push(`Direct selection (${leads.length} POC${leads.length > 1 ? 's' : ''} found)`);
    } else {
      if (sb.poc_match   > 0) reasons.push(`POC title match (+${sb.poc_match})`);
      if (sb.hr_fallback > 0) reasons.push(`HR/Talent fallback (+${sb.hr_fallback})`);
      if (sb.seniority   > 0) reasons.push(`Seniority fallback (+${sb.seniority})`);
    }
    reasons.push(`Email: ${lead.email_type} (+${sb.email})`);
    if (sb.linkedin_bonus) reasons.push(`LinkedIn bonus (+${sb.linkedin_bonus})`);

    const matchType = isDirect
      ? 'DIRECT_SELECT'
      : lead._context?.poc_match_fired         ? 'POC_MATCH'
      : lead._context?.hr_fallback_fired        ? 'HR_FALLBACK'
